import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import ItemList from 'flarum/common/utils/ItemList';
import classList from 'flarum/common/utils/classList';
import CountUp from './CountUp';
/**
 * A strip of headline community numbers. The "right now" stats lead, so the
 * page opens on activity rather than history.
 */
export default class CommunityPulse extends Component {
  view() {
    const items = this.statItems();
    if (items.isEmpty()) return null;
    return m("section", {
      className: "CommunityPulse",
      "aria-label": app.translator.trans('flarum-discuss.forum.home.pulse_label', {}, true)
    }, items.toArray());
  }
  statItems() {
    const items = new ItemList();
    const stats = app.forum.attribute('communityStats');
    if (!stats) return items;

    // fof/online-users-widget already computes this per actor, honouring discloseOnline and visibility.
    if ('fof-online-users-widget' in flarum.extensions) {
      var _app$forum$attribute;
      items.add('onlineNow', this.stat('fas fa-circle', (_app$forum$attribute = app.forum.attribute('totalOnlineUsers')) != null ? _app$forum$attribute : 0, app.translator.trans('flarum-discuss.forum.home.stats.online_now'), 'live'), 100);
    }
    items.add('postsToday', this.stat('fas fa-bolt', stats.postsToday, app.translator.trans('flarum-discuss.forum.home.stats.posts_today')), 90);
    items.add('newMembersWeek', this.stat('fas fa-user-plus', stats.newMembersWeek, app.translator.trans('flarum-discuss.forum.home.stats.new_members_week')), 80);
    if (stats.questionsSolved !== null) {
      items.add('questionsSolved', this.stat('fas fa-check-circle', stats.questionsSolved, app.translator.trans('flarum-discuss.forum.home.stats.questions_solved')), 70);
    }
    items.add('members', this.stat('fas fa-users', stats.members, app.translator.trans('flarum-discuss.forum.home.stats.members'), 'total'), 60);
    items.add('discussions', this.stat('fas fa-comments', stats.discussions, app.translator.trans('flarum-discuss.forum.home.stats.discussions'), 'total'), 50);
    items.add('posts', this.stat('fas fa-pen', stats.posts, app.translator.trans('flarum-discuss.forum.home.stats.posts'), 'total'), 40);
    return items;
  }

  /**
   * `total` stats are all-time figures; on phones only the recent-activity stats are shown.
   */
  stat(icon, value, label, kind) {
    return m("div", {
      className: classList('CommunityPulse-stat', kind && "CommunityPulse-stat--".concat(kind))
    }, m(Icon, {
      name: icon,
      className: "CommunityPulse-icon"
    }), m("div", {
      className: "CommunityPulse-value"
    }, m(CountUp, {
      value: value
    })), m("div", {
      className: "CommunityPulse-label"
    }, label));
  }
}
flarum.reg.add('flarum-discuss', 'forum/components/CommunityPulse', CommunityPulse);